$CompressedBytes = [Convert]::FromBase64String(($CompressedBase64 -replace '\s',''))
$SourceInput = New-Object System.IO.MemoryStream (,$CompressedBytes)
$GzipStream = New-Object System.IO.Compression.GZipStream($SourceInput,[System.IO.Compression.CompressionMode]::Decompress)
$OutputBuffer = New-Object System.IO.MemoryStream
try { $GzipStream.CopyTo($OutputBuffer) } finally { $GzipStream.Dispose(); $SourceInput.Dispose() }
[System.IO.File]::WriteAllBytes($PyFile,$OutputBuffer.ToArray())
$OutputBuffer.Dispose()
$FoundHash = (Get-FileHash -LiteralPath $PyFile -Algorithm SHA256).Hash.ToUpperInvariant()
if ($FoundHash -ne '71B317867D3131827110F4AC01DD13CCFB7A616C189B7498FF62992FFF9107FA') { throw 'INTEGRITY_FAILURE_EMBEDDED_PYTHON_SHA256' }
$RepoPython = Join-Path $Repo '.venv\Scripts\python.exe'
if (Test-Path -LiteralPath $RepoPython) { $Python = $RepoPython; $PyPrefix = @() }
elseif (Get-Command 'py.exe' -ErrorAction SilentlyContinue) { $Python = 'py.exe'; $PyPrefix = @('-3') }
elseif (Get-Command 'python.exe' -ErrorAction SilentlyContinue) { $Python = 'python.exe'; $PyPrefix = @() }
else { throw 'PYTHON_NOT_FOUND: Python3 or repo .venv required; no pip used' }
$ArgsList = @($PyFile, '--repo', $Repo, '--downloads', $Dl, '--archive-budget-gb', [string]$ArchiveBudgetGB, '--packet-mb', [string]$PacketMB)
if ($SkipMinute) { $ArgsList += '--skip-minute' }
if ($SkipAggTrades) { $ArgsList += '--skip-aggtrades' }
$Log = Join-Path $Work 'C2_MEGA_EXECUTION_TRANSCRIPT.txt'
$TranscriptStarted = $false
try {
    Start-Transcript -Path $Log -Force | Out-Null
    $TranscriptStarted = $true
    Write-Host ('AKAH_C2_RESEARCH=SOURCE_FIRST_PRE2024_NO_LIVE')
    Write-Host ('ARCHIVE_BUDGET_GB=' + $ArchiveBudgetGB)
    Write-Host ('WORK_DIR=' + $Work)
    & $Python @PyPrefix @ArgsList
    $Exit = $LASTEXITCODE
} finally {
    if ($TranscriptStarted) { Stop-Transcript | Out-Null }
}
$Output = Join-Path $Dl 'AKAH_C2_MARKET_VAULT_UPLOAD_PACKETS'
Write-Host ('UPLOAD_PACKET_FOLDER=' + $Output)
Write-Host 'PLEASE_UPLOAD_ANALYSIS_AND_COVERAGE_ZIP_FIRST'
if ($Exit -ne 0) { Write-Host ('AKAH_C2_EXIT_CODE=' + $Exit); exit $Exit }
Write-Host 'AKAH_C2_MEGA_TERMINAL_RUN_COMPLETE_WITH_REPORTED_GAPS'
